```python
# Function to check if a number is square-free
def is_square_free(n):
    if n < 2:
        return False
    for i in range(2, int(n**0.5) + 1):
        if i * i <= n:
            # Check if n is a perfect square
            return False
    return True

# Count the number of positive odd integers greater than 1 and less than 100 that are square-free
count = 0
for i in range(3, 100, 2):
    if is_square_free(i):
        count += 1

print(count)
